WHO = {'bridge': [('alphafoldmicro', 128482), ('norelicro', 128610), ('norelalo', 0), ('nordu', 128866), ('norelalo', 0), ('psiloldmicro', 130078), ('quodldmicro', 130271), ('norelicro', 130783)], 'column': [('kivdmelicro', 128482), ('elmamesof', 128610), ('eineyccfools', 0), ('kivdools', 128674), ('senddeben', 128866), ('einsof', 0), ('elmamdmkum', 0), ('elmamdmicro', 128928)], 'manor': [('norelcfools', 128674), ('temseyeben', 129694), ('elmamddeben', 131038), ('senddash', 0), ('norelcfools', 0), ('temseeeyeben', 139085), ('temseyeben', 0), ('elmamddeben', 142468)], 'tree': [('aprilcut', 0), ('temseeeyeben', 131486), ('lotdmicro', 0), ('bridelcut', 133656), ('temseeeyeben', 0), ('temseeeyeben', 138192), ('bridelcut', 0), ('temseeeyeben', 139852)], 'tower': [('muddsof', 0), ('unkum', 134040), ('mulicro', 135061), ('eineycddeben', 0), ('noreelicro', 137425), ('shalo', 138064), ('solnor', 141256), ('einsof', 143426)], 'temple': [('norelalo', 0), ('psiloceyeben', 0), ('lotdmicro', 132826), ('norelcfools', 0), ('aprilcut', 139342), ('lotdmicro', 0)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW292(OracleReleaseRuntimeW291):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
